insert into public.explanation_templates (anomaly_type, en, hi) values
  ('idle_excess'::public.anomaly_type, '{machine} idled {idle_pct}% of the last hour, {ratio}× its normal. About {fuel_l} L of diesel (≈ ₹{cost_inr}).', '{machine} पिछले एक घंटे में {idle_pct}% समय खाली चली, सामान्य से {ratio} गुना। लगभग {fuel_l} लीटर डीज़ल (≈ ₹{cost_inr})।'),
  ('seatbelt_off_moving'::public.anomaly_type, '{machine} moved at {speed_kmh} km/h with the seatbelt off on a {pitch_deg}° slope.', '{machine} {pitch_deg}° ढलान पर बिना सीटबेल्ट {speed_kmh} किमी/घंटा चली।'),
  ('overspeed'::public.anomaly_type, '{machine} ran at {speed_kmh} km/h in a {limit_kmh} km/h zone.', '{machine} {limit_kmh} किमी/घंटा ज़ोन में {speed_kmh} किमी/घंटा चली।'),
  ('slope_exceeded'::public.anomaly_type, '{machine} worked on a {pitch_deg}° slope; the limit is {limit_deg}°.', '{machine} {pitch_deg}° ढलान पर चली; सीमा {limit_deg}° है।'),
  ('fault_continued_operation'::public.anomaly_type, '{machine} kept working for {minutes} min with fault {code} active.', '{machine} फ़ॉल्ट {code} के साथ {minutes} मिनट चलती रही।'),
  ('hydraulic_temp_drift'::public.anomaly_type, '{machine} hydraulic oil is at {value}°C, rising above its normal {mean}°C.', '{machine} का हाइड्रोलिक तेल {value}°C है, सामान्य {mean}°C से ऊपर।'),
  ('coolant_temp_drift'::public.anomaly_type, '{machine} coolant is at {value}°C, above its normal {mean}°C.', '{machine} का कूलेंट {value}°C है, सामान्य {mean}°C से ऊपर।')
